package com.bank.rateband.service;

import java.util.List;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Finds the smallest range covering at least one element from each sorted list.
public class RateBandService {
    private static final Logger log = Logger.getLogger(RateBandService.class.getName());

    public int[] smallestRange(List<List<Integer>> lists) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        int currentMax = Integer.MIN_VALUE;
        for (int i = 0; i < lists.size(); i++) {
            int first = lists.get(i).get(0);
            pq.add(new int[]{first, i, 0});          // one element per list
            currentMax = Math.max(currentMax, first);
        }
        int rangeStart = 0, rangeEnd = Integer.MAX_VALUE;   // widest possible initial band
        while (pq.size() == lists.size()) {                 // all lists still represented
            int[] top = pq.poll();
            int min = top[0];
            if (currentMax - min < rangeEnd - rangeStart) {  // strictly tighter wins
                rangeStart = min;
                rangeEnd = currentMax;
            }
            int li = top[1], ei = top[2];
            if (ei + 1 < lists.get(li).size()) {
                int next = lists.get(li).get(ei + 1);
                pq.add(new int[]{next, li, ei + 1});
                currentMax = Math.max(currentMax, next);
            }
        }
        final int s = rangeStart, e = rangeEnd;
        log.info(() -> "Smallest covering band = [" + s + ", " + e + "]");
        return new int[]{rangeStart, rangeEnd};
    }
}
