package com.bank.rateband;

import com.bank.rateband.service.RateBandService;
import java.util.List;
import java.util.logging.Logger;

public class RateBandApplication {
    private static final Logger log = Logger.getLogger(RateBandApplication.class.getName());

    public static void main(String[] args) {
        RateBandService service = new RateBandService();
        List<List<Integer>> lists = List.of(
            List.of(4, 10, 15, 24),   // lender 1 rates (basis points, scaled)
            List.of(0, 9, 12, 20),    // lender 2 rates
            List.of(5, 18, 22, 30)    // lender 3 rates
        );
        int[] band = service.smallestRange(lists);
        log.info("Tightest covering band: [" + band[0] + ", " + band[1] + "]");
    }
}
